#controls { position: absolute; top: 10px; left: 10px; z-index: 10; }
#controls button { margin: 5px; padding: 5px 10px; font-size: 18px; background: #0f0f1a; color: #fff; border: none; border-radius: 5px; cursor: pointer; }
#controls .btn:active { background: #000; }
#status { position: absolute; top: 10px; right: 10px; z-index: 10; }
#status .score { font-size: 24px; color: #4caf50; font-weight: bold; }
#status .next { font-size: 20px; color: #2196f3; }
#status .gameover { font-size: 24px; color: #ff5252; font-weight: bold; }
#keyhints { position: absolute; bottom: 10px; left: 10px; z-index: 10; font-size: 14px; color: #555; }
