<body>
<canvas id="canvas" style="grid-template-columns: repeat(40, 1fr); min-height: 600px;"></canvas>
<div id="controls">
  <button id="up">↑</button>
  <button id="down">↓</button>
  <button id="left">←</button>
  <button id="right">→</button>
  <button id="space">空</button>
</div>
<div id="status">
  <div class="score">Score: 0</div>
  <div class="next">Next: <span id="nextpiece">none</span></div>
</div>
<div id="keyhints">Wickeln & Steuerung</div>
