const keysB = { a: 97, w: 119, s: 115, d: 100, arrowup: 38, arrowdown: 40, arrowleft: 37, arrowright: 39, space: 32 };

const pieces = {
  I: [ [1,1,1,1], [0,0,0,0] ],
  J: [ [1,0,1,1], [0,0,0,0] ],
  L: [ [1,1,1,0], [0,0,0,0] ],
  O: [ [1,1,1,1], [0,0,0,0] ],
  S: [ [1,1,0,0], [1,0,0,0] ],
  T: [ [1,1,1,0], [0,0,0,0] ],
  Z: [ [1,0,1,1], [0,0,0,0] ]
};

