  document.getElementById('canvas').style.gridTemplateColumns = `repeat(${WIDTH}, 1fr)`;
  tiles.forEach((_, y) => {
    for (let x = 0; x < WIDTH; x++) {
      let cell = null;
      if (currentPiece && currentPiece.rotation !== undefined) {
        for (let i = 0; i < currentPiece.width; i++) {
          for (let j = 0; j < currentPiece.height; j++) {
            if (currentPiece.rotation === j && currentPiece.type === i) {
              let ny = y + j, nx = x + i;
              if (ny < HEIGHT && nx < WIDTH && tiles[ny][nx]) cell = tiles[ny][nx];
            }
          }
        }
      } else if (tiles[0][0]) {
        // O
        for (let j = 0; j < 4; j++) for (let i = 0; i < 4; i++) { if (tiles[j][i]) cell = tiles[j][i]; }
      } else if (pieces[currentPiece.type]) {
        for (let j = 0; j < 4; j++) for (let i = 0; i < 4; i++) { if (pieces[currentPiece.type][j][i]) cell = pieces[currentPiece.type][j][i]; }
      }
